using System.Text.Json;namespace SobhanNotificationHub.Services;public sealed class AppSettings{public string SiteUrl{get;set;}="https://sobhansb.ir";public bool DevelopmentAllowHttp{get;set;}public bool LocalSoundEnabled{get;set;}=true;public bool LocalShowBody{get;set;}=true;public string DeviceUid{get;set;}="";public static string DataDirectory=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SobhanNotificationHub");public static AppSettings Load(){Directory.CreateDirectory(DataDirectory);var source=Path.Combine(AppContext.BaseDirectory,"appsettings.json");var local=Path.Combine(DataDirectory,"appsettings.json");try{var path=File.Exists(local)?local:source;var json=File.ReadAllText(path);return JsonSerializer.Deserialize<AppSettings>(json,new JsonSerializerOptions{PropertyNameCaseInsensitive=true,PropertyNamingPolicy=JsonNamingPolicy.SnakeCaseLower})??new();}catch(Exception ex){LoggingService.Error("settings_load",ex);return new();}}public void Save(){Directory.CreateDirectory(DataDirectory);File.WriteAllText(Path.Combine(DataDirectory,"appsettings.json"),JsonSerializer.Serialize(this,new JsonSerializerOptions{WriteIndented=true,PropertyNamingPolicy=JsonNamingPolicy.SnakeCaseLower}));}}
